from common import *


def overlap(a, b, k):
    assert set(a) == set(b)
    values = [len(set(a[d]) & set(b[d])) / k for d in a]
    return {"mean": sum(values) / len(values), "days": len(values), "identical_days": sum(v == 1 for v in values)}


def main():
    save_source(__file__)
    progress = read(PROGRESS)
    prepared = read(BASE / "configs/prepared-inputs.json")
    expected = {(v, seed) for v in VARIANTS if prepared["variants"][v].get("paired_fits_needed") for seed in SEEDS}
    normal_end = progress["status"] == "evaluation_complete_awaiting_review"
    rows, incomplete = [], []
    for variant in VARIANTS:
        if not prepared["variants"][variant].get("paired_fits_needed"):
            continue
        paths = {t: BASE / "data" / f"{variant}-{t}-formal-heads.json" for t in ["new", "old"]}
        if not all(p.exists() for p in paths.values()):
            incomplete.append({"variant": variant, "reason": "Paired formal head files unavailable; no pair claimed."})
            continue
        receipts = progress["scientific_candidates"][variant]["treatments"]
        if not all(receipts.get(t, {}).get("status") == "completed" for t in paths):
            incomplete.append({"variant": variant, "reason": "Both canonical evaluation receipts are not complete; no pair claimed."})
            continue
        evaluations = {t: read(BASE / "metrics" / f"{variant}-{t}.json") for t in paths}
        for treatment, p in paths.items():
            check(receipts[treatment]["evaluation"])
            check(receipts[treatment]["prediction_proof"])
            assert receipts[treatment]["evaluation"] == fingerprint(BASE / "metrics" / f"{variant}-{treatment}.json")
            assert evaluations[treatment]["label_grading"]["prediction_proof"] == receipts[treatment]["prediction_proof"]
            receipt = evaluations[treatment]["diagnostic_heads"]
            assert (ROOT / receipt["path"]).resolve() == p.resolve()
            check(receipt)
        heads = {t: read(p) for t, p in paths.items()}
        dates = set(heads["new"]["seeds"][str(SEEDS[0])]["3"])
        assert len(dates) == 1448
        for h in heads.values():
            assert set(h["seeds"]) == {str(s) for s in SEEDS}
            for panel in [*h["seeds"].values(), h["ensemble"]]:
                for k in [3, 5]:
                    assert set(panel[str(k)]) == dates
                    assert all(len(v) == len(set(v)) == k for v in panel[str(k)].values())
        for seed in SEEDS:
            matches = {t: [j for j in progress["jobs"] if j["variant"] == variant and j["treatment"] == t and j["seed"] == seed and j["status"] == "succeeded"] for t in ["new", "old"]}
            assert all(len(m) == 1 for m in matches.values())
            jobs = {t: m[0] for t, m in matches.items()}
            records = {}
            for treatment, job in jobs.items():
                assert job["status"] == "succeeded"
                evaluated = [s for s in evaluations[treatment]["sessions"] if s["seed"] == seed]
                assert len(evaluated) == 1 and evaluated[0]["session"] == job["session"]
                check(job["evidence"])
                records[treatment] = read(ROOT / job["evidence"]["path"])
            a, b = records["new"], records["old"]
            n = min(len(a["rounds"]), len(b["rounds"]))
            tree_diff = next((i + 1 for i in range(n) if a["rounds"][i]["tree_sha256"] != b["rounds"][i]["tree_sha256"]), None)
            metric_diff = next((i + 1 for i in range(n) if a["rounds"][i]["objective"] != b["rounds"][i]["objective"]), None)
            rows.append({
                "variant": variant, "seed": seed, "common_observed_rounds": n,
                "first_tree_serialization_difference": tree_diff,
                "first_early_stopping_metric_difference": metric_diff,
                "selected_rounds": {t: r["early_stopping"][0]["best_iteration"] for t, r in records.items()},
                "formal_head_overlap": {str(k): overlap(heads["new"]["seeds"][str(seed)][str(k)], heads["old"]["seeds"][str(seed)][str(k)], k) for k in [3, 5]},
                "evidence": {t: job["evidence"] for t, job in jobs.items()},
            })
    covered = {(r["variant"], r["seed"]) for r in rows}
    assert covered <= expected and len(covered) == len(rows)
    if normal_end:
        assert covered == expected
    result = {
        "status": "complete" if covered == expected else "partial",
        "expected_pairs": len(expected), "missing_pairs": sorted(expected - covered), "incomplete_reasons": incomplete,
        "width5_exclusion": "No frozen old raw-return magnitudes; no valid paired old-label input.",
        "purpose": "Within-seed old/new label sensitivity; no new fit or selection.",
        "interpretation": "A tree hash difference includes leaf values and does not prove a split-structure difference. Round comparisons cover only the common observed prefix. Formal head sets use canonical inference and filters, not the early-stop input shortcut.",
        "pairs": rows,
        "head_sources": [fingerprint(p) for p in sorted((BASE / "data").glob("*-formal-heads.json"))],
    }
    write(BASE / "docs/paired-seed-diagnostics.json", result)
    print("Paired diagnostics:", len(rows), "same-seed pairs")


if __name__ == "__main__":
    main()
